/**
 * Unit tests for ValuedEnum#compareTo
 */
public class ValuedEnum_compareTo_TriageGen2Test {

    /**
     * Implementation of ValuedEnum for testing purposes.
     * Since the constructor is protected, we create a concrete subclass.
     */
    private static class TestValuedEnum extends ValuedEnum {
        protected TestValuedEnum(String name, int value) {
            super(name, value);
        }
    }

    @Test
