import org.apache.commons.lang.ClassUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ValuedEnum#compareTo
 */
public class ValuedEnum_compareTo_TriageGen2Test {

    /**
     * Implementation of ValuedEnum for testing purposes.
     * Since the constructor is protected, we create a concrete subclass.
     */
    private static class TestValuedEnum extends ValuedEnum {
        protected TestValuedEnum(String name, int value) {
            super(name, value);
        }
    }







    @Test(expected = ClassCastException.class)
    public void testCompareTo_WrongObjectType() {
        ValuedEnum enum1 = new TestValuedEnum("A", 10);
        Object notAnEnum = "I am a string";

        // This should trigger ClassCastException: (ValuedEnum) other
        enum1.compareTo(notAnEnum);
    }


}

